const body = $input.first().json.body || $input.first().json;
const post = body.post || '';
const tech = body.tech || '';
const type = body.type || 'Projet technique';

const prompt = `Analyse ce post LinkedIn et génère UNE requête de recherche d'image en anglais (3-5 mots max) qui illustrerait parfaitement ce post de façon professionnelle.

Post: ${post.substring(0, 600)}
Technologies: ${tech}

Réponds UNIQUEMENT avec la requête en anglais, rien d'autre. Exemples: "cloud security dashboard professional", "web app authentication login", "nodejs api backend architecture"`;

return [{ json: { post, tech, type, prompt } }];

const response = $input.first().json;
const prev = $('Analyze Content').first().json;

let imageQuery = 'professional developer workspace technology';
try {
  imageQuery = response.choices[0].message.content.trim().replace(/"/g, '').replace(/\n/g, ' ');
} catch(e) {
  imageQuery = 'professional developer workspace technology';
}

const tech = prev.tech || '';
const techList = tech.split(',').map(t => t.trim().toLowerCase()).filter(Boolean);
const postLower = prev.post.toLowerCase();

let docLinks = [];
let tips = [];

// Docs selon contexte
if (postLower.includes('accès') || postLower.includes('auth') || postLower.includes('sécurité') || postLower.includes('login')) {
  docLinks.push({ title: 'OWASP Auth Cheatsheet', url: 'https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html', type: 'reference' });
  docLinks.push({ title: 'JWT.io', url: 'https://jwt.io/', type: 'tool' });
}
if (techList.includes('prisma')) {
  docLinks.push({ title: 'Prisma Documentation', url: 'https://www.prisma.io/docs', type: 'reference' });
}
if (techList.includes('react') || techList.includes('next.js')) {
  docLinks.push({ title: 'React Documentation', url: 'https://react.dev/', type: 'reference' });
}
if (techList.some(t => ['node.js', 'express', 'nodejs'].includes(t))) {
  docLinks.push({ title: 'Node.js Best Practices', url: 'https://github.com/goldbergyoni/nodebestpractices', type: 'github' });
}
if (techList.some(t => ['aws', 'gcp', 'azure', 'cloud'].includes(t))) {
  docLinks.push({ title: 'AWS Architecture Center', url: 'https://aws.amazon.com/architecture/', type: 'reference' });
}
if (techList.some(t => ['docker', 'kubernetes', 'k8s'].includes(t))) {
  docLinks.push({ title: 'Docker Best Practices', url: 'https://docs.docker.com/develop/dev-best-practices/', type: 'reference' });
}
if (techList.includes('n8n')) {
  docLinks.push({ title: 'n8n Documentation', url: 'https://docs.n8n.io/', type: 'reference' });
}
if (techList.some(t => ['python', 'pandas', 'numpy'].includes(t))) {
  docLinks.push({ title: 'Python Best Practices', url: 'https://docs.python-guide.org/', type: 'reference' });
}
if (techList.some(t => ['postgresql', 'mysql', 'mongodb', 'supabase'].includes(t))) {
  docLinks.push({ title: 'Database Design Guide', url: 'https://www.postgresql.org/docs/current/index.html', type: 'reference' });
}
if (techList.some(t => ['html', 'css', 'javascript'].includes(t))) {
  docLinks.push({ title: 'MDN Web Docs', url: 'https://developer.mozilla.org/', type: 'reference' });
}

// Tips selon type de post
if (postLower.includes('projet') || postLower.includes('app') || postLower.includes('application')) {
  tips.push('Une démo GIF ou vidéo de ton app génère 3x plus d engagement qu une image statique');
}
if (postLower.includes('automatisation') || postLower.includes('workflow')) {
  tips.push('Une capture de ton workflow n8n est le visuel idéal pour ce type de post');
}
if (postLower.includes('conseil') || postLower.includes('astuce')) {
  tips.push('Un carousel LinkedIn (PDF multi-pages) performe mieux qu une image simple pour les conseils');
}

tips.push('Poste entre 8h-10h ou 17h-19h pour maximiser la visibilité');
tips.push('Les posts avec image génèrent 40% plus d engagement sur LinkedIn');

return [{ json: { imageQuery, docLinks, tips, visualType: imageQuery } }];

const unsplash = $input.first().json;
const buildQuery = $('Build Query').first().json;

let images = [];

if (unsplash.results && unsplash.results.length > 0) {
  images = unsplash.results.map(img => ({
    url: img.urls.regular,
    thumb: img.urls.small,
    alt: img.alt_description || buildQuery.imageQuery,
    author: img.user.name,
    authorLink: img.user.links.html,
    credit: 'Photo by ' + img.user.name + ' on Unsplash',
    downloadLocation: img.links.download_location
  }));
} else {
  // Fallback si Unsplash ne retourne rien
  images = [{
    url: 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&q=80',
    thumb: 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=400&q=80',
    alt: 'Technology',
    author: 'Unsplash',
    authorLink: 'https://unsplash.com',
    credit: 'Photo on Unsplash',
    downloadLocation: ''
  }];
}

return [{
  json: {
    success: true,
    suggestedVisualType: buildQuery.visualType,
    searchQuery: buildQuery.imageQuery,
    images,
    documents: buildQuery.docLinks,
    tips: buildQuery.tips,
    generatedAt: new Date().toISOString()
  }
}];
